/**
 * Returns the values that appear more than once, in the order each duplicate is FIRST discovered.
 * @param {Array} arr - Input array of any type (numbers, strings, objects, etc.)
 * @returns {Array} Array of duplicate values in discovery order
 */
function findDuplicates(arr) {
    const seen = new Set();
    const duplicates = [];

    for (const item of arr) {
        if (seen.has(item)) {
            // Only add to duplicates the first time we see a duplicate
            if (!seen.has(item)) {
                duplicates.push(item);
            }
        } else {
            seen.add(item);
        }
    }

    return duplicates;
}
```

