```js
/**
 * Checks if a string has valid bracket sequences.
 * Non-bracket characters are ignored.
 * 
 * @param {string} s - The input string to check
 * @returns {boolean} - True if all brackets are properly matched and nested
 */
function isValidBrackets(s) {
    // Handle invalid input types
    if (s === null || typeof s !== 'string') {
        return false;
    }

    const stack = [];
    const bracketPairs = {
        '(': ')',
        '[': ']',
        '{': '}'
    };

    for (let i = 0; i < s.length; i++) {
        const char = s[i];

        // If it's an opening bracket, push to stack
        if (bracketPairs.hasOwnProperty(char)) {
            stack.push(char);
        } 
        // If it's a closing bracket
        else if ([')', ']', '}'].includes(char)) {
            // If stack is empty, there's no matching opening bracket
            if (stack.length === 0) {
                return false;
            }

            // Pop the last opening bracket and check if it matches
            const lastOpening = stack.pop();
            if (bracketPairs[lastOpening] !== char) {
                return false;
            }
        }
        // Non-bracket characters are ignored
    }

    // If stack is empty, all brackets were properly closed
    return stack.length === 0;
}
```

